  --secondary-foreground: #e4e4e4;
  --muted: #454545;
  --muted-foreground: #a4a4a4;
  --accent: #6394eb;
  --accent-foreground: #e4e4e4;
  --destructive: #f14444;
  --destructive-foreground: #ffffff;
  --border: #454545;
  --input: #454545;
  --ring: #39a85c;
  --chart-1: #39a85c;
  --chart-2: #4683b5;
  --chart-3: #6394eb;
  --chart-4: #64daf1;
  --chart-5: #1b9641;
  --radius: 0.5rem;
  --sidebar: #1b1d22;
  --sidebar-foreground: #e4e4e4;
  --sidebar-primary: #39a85c;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #6394eb;
  --sidebar-accent-foreground: #e4e4e4;
  --sidebar-border: #454545;
  --sidebar-ring: #39a85c;
  --font-sans: Plus Jakarta Sans, sans-serif;
